open System
open System.Collections.Generic
open System.Net.Http
open System.Threading
open Grace.Types.Common
open Grace.Types.DirectoryVersion
open Grace.Types.Repository
open Grace.Actors.Services
open Grace.Shared
open Grace.Shared.Utilities
open Microsoft.Azure.Cosmos
open NodaTime

let check name ok = if not ok then failwith name else printfn "PASS: %s" name
let run = task {
    let options = CosmosClientOptions(ConnectionMode = ConnectionMode.Gateway, LimitToEndpoint = true, UseSystemTextJsonSerializerWithOptions = Constants.JsonSerializerOptions)
    options.HttpClientFactory <- fun () ->
        let handler = new HttpClientHandler()
        handler.ServerCertificateCustomValidationCallback <- HttpClientHandler.DangerousAcceptAnyServerCertificateValidator
        new HttpClient(handler)
    use client = new CosmosClient("https://127.0.0.1:18081", "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==", options)
    use deadline = new CancellationTokenSource(TimeSpan.FromSeconds 90.)
    let token = deadline.Token
    let databaseName = "ops-1047-" + Guid.NewGuid().ToString("N")
    let! databaseResponse = client.CreateDatabaseAsync(databaseName, cancellationToken = token)
    let database = databaseResponse.Database
    let! containerResponse = database.CreateContainerAsync("events", "/PartitionKey", cancellationToken = token)
    let container = containerResponse.Container
    let repo = Guid.NewGuid()
    let emptyRepo = Guid.NewGuid()
    let foreignRepo = Guid.NewGuid()
    let owner = Guid.NewGuid()
    let org = Guid.NewGuid()
    let timestamp = Instant.FromUtc(2026,9,7,0,0)
    let metadata = { Timestamp = timestamp; CorrelationId = "ops-1047-preflight"; Principal = "fixture"; ClientType = None; Properties = Dictionary<string,string>() }
    let persistRepository repositoryId = task {
        let events : RepositoryEvent array = [| { Event = RepositoryEventType.Created("preflight", repositoryId, owner, org, ObjectStorageProvider.AzureBlobStorage); Metadata = metadata } |]
        let doc = {| id = string repositoryId; GrainType = Grace.Actors.Constants.StateName.Repository; PartitionKey = string org; State = events |}
        let! _ = container.CreateItemAsync(doc, PartitionKey(string org), cancellationToken = token)
        return () }
    do! persistRepository repo
    do! persistRepository emptyRepo
    let persistDirectory repositoryId grainType index = task {
        let directory = DirectoryVersion()
        directory.DirectoryVersionId <- Guid.NewGuid()
        directory.RepositoryId <- repositoryId
        directory.OwnerId <- owner
        directory.OrganizationId <- org
        directory.CreatedAt <- timestamp
        directory.Files.Add(FileVersion.CreateWithHashes (string index + ".txt") (String.replicate 64 "a") (String.replicate 64 "b") "" true 10L)
        let events : DirectoryVersionEvent array = [| { Event = DirectoryVersionEventType.Created directory; Metadata = metadata }; { Event = DirectoryVersionEventType.LogicalDeleted "retained"; Metadata = metadata } |]
        let doc = {| id = string directory.DirectoryVersionId; GrainType = grainType; PartitionKey = string repositoryId; State = events |}
        let! _ = container.CreateItemAsync(doc, PartitionKey(string repositoryId), cancellationToken = token)
        return doc.id }
    let ids = ResizeArray<string>()
    let mutable i = 0
    while i < 5 do
        let! id = persistDirectory repo Grace.Actors.Constants.StateName.DirectoryVersion i
        ids.Add id
        i <- i + 1
    let! _ = persistDirectory foreignRepo Grace.Actors.Constants.StateName.DirectoryVersion 99
    let! _ = persistDirectory repo "excluded-grain" 98
    let enumerate repositoryId = task {
        let repositoryQuery = QueryDefinition("SELECT c.State FROM c WHERE c.GrainType = @grainType AND c.State[0].Event.created.repositoryId = @repositoryId AND c.PartitionKey = @partitionKey").WithParameter("@grainType", Grace.Actors.Constants.StateName.Repository).WithParameter("@repositoryId", string repositoryId).WithParameter("@partitionKey", string org)
        use repositories = container.GetItemQueryIterator<RepositoryEventValue>(repositoryQuery, requestOptions = QueryRequestOptions(PartitionKey = PartitionKey(string org)))
        let! repositoryPage = repositories.ReadNextAsync token
        if repositoryPage.Count <> 1 then return Error "repository-absent"
        else
            let query = QueryDefinition("SELECT c.State FROM c WHERE c.GrainType = @grainType AND c.PartitionKey = @partitionKey").WithParameter("@grainType", Grace.Actors.Constants.StateName.DirectoryVersion).WithParameter("@partitionKey", string repositoryId)
            use iterator = container.GetItemQueryIterator<DirectoryVersionEventValue>(query, requestOptions = QueryRequestOptions(PartitionKey = PartitionKey(string repositoryId), MaxItemCount = 2))
            let mutable pages = 0
            let mutable bytes = 0L
            let mutable docs = 0
            while iterator.HasMoreResults do
                let! page = iterator.ReadNextAsync token
                pages <- pages + 1
                page.Resource |> Seq.iter (fun row ->
                    let dto = row.State |> Array.fold (fun dto event -> DirectoryVersionDto.UpdateDto event dto) DirectoryVersionDto.Default
                    check "real persisted scope and retained logical deletion" (dto.DirectoryVersion.RepositoryId = repositoryId && dto.DeletedAt.IsSome)
                    bytes <- bytes + (dto.DirectoryVersion.Files |> Seq.sumBy _.Size)
                    docs <- docs + 1)
            return Ok (bytes, docs, pages) }
    let! known = enumerate repo
    check "complete real pagination excludes foreign partition and grain" (match known with Ok (50L, 5, pages) -> pages >= 3 | _ -> false)
    let! zero = enumerate emptyRepo
    check "existing repository has valid zero" (match zero with Ok (0L,0,_) -> true | _ -> false)
    let! absent = enumerate (Guid.NewGuid())
    check "absent repository cannot report zero" (absent = Error "repository-absent")
    let mutable index = 0
    while index < ids.Count do
        let! _ = container.DeleteItemAsync<obj>(ids[index], PartitionKey(string repo), cancellationToken = token)
        index <- index + 1
    let! removed = enumerate repo
    check "physical source removal yields zero without reading blobs" (match removed with Ok (0L,0,_) -> true | _ -> false)
    printfn "RESULT database=%s initial=%A empty=%A absent=%A removed=%A" databaseName known zero absent removed
    let! _ = database.DeleteAsync(cancellationToken = token)
    return () }
run.GetAwaiter().GetResult()
